def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 3 and expr[0] == 'and':
            a, b, c = expr[1], expr[2], expr[3]
            if a == b:
                result.append(a)
            elif a == c:
                result.append(a)
            elif b == c:
                result.append(b)
        elif isinstance(expr, tuple) and len(expr) == 3 and expr[0] == 'or':
            a, b, c = expr[1], expr[2], expr[3]
            if a == b:
                result.append(a)
            elif a == c:
                result.append(a)
            elif b == c:
                result.append(b)
        else:
            result.append(expr)
    return result

