import json
from xml.etree import ElementTree as ET
from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        root = ET.fromstring(document)
        xrd = root.find('{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD')
        if xrd is not None:
            subject = xrd.find('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject').text
            links = []
            for link in xrd.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
                href = link.get('href')
                rel = link.get('rel')
                if href and rel:
                    links.append({'href': href, 'rel': rel})
            return {'subject': subject, 'links': links}
        else:
            raise ValueError("Invalid Diaspora webfinger document")

